    "materiRingkas": [
      {
        "judul": "Berpikir Kritis & Mencintai Iptek",
        "isi": "A. Berpikir Kritis & Mencintai Iptek (Soal No. 1 – 13) Q.S. Ali 'Imran/3: 190–191 (Berpikir Kritis & Tanda Ulil Albab): Ayat 190 menegaskan bahwa dalam penciptaan langit dan bumi serta pergantian malam dan siang terdapat tanda-tanda kebesaran Allah bagi Ulil Albab (orang-orang yang berakal sehat dan jernih). Ayat 191 menjelaskan ciri utama Ulil Albab, yaitu senantiasa berzikir mengingat Allah dalam keadaan berdiri, duduk, maupun berbaring, serta memikirkan (tafakkur) penciptaan langit dan bumi seraya menyimpulkan bahwa tidak ada satu pun ciptaan Allah yang sia-sia. Hukum Tajwid Penting pada Q.S. Ali 'Imran/3: 190–191 (Soal 3): Alif Lam Syamsiyah (Idgham Syamsiyah): Pada lafaz ِتٰﻮٰاﻟﺴﱠﻤ ِﻖْﻠَﺧ ﻲِﻓ( huruf lam tidak dibaca, langsung masuk ke huruf sin bertasydid). Alif Lam Qamariyah (Izhar Qamariyah): Pada lafaz ِضْرَْ اﻻَو dan ِﺎبَﺒْﻟَْ اﻻ( huruf lam sukun dibaca jelas). Ghunnah Musyaddadah: Pada lafaz نﱠِا( huruf nun bertasydid dibaca dengung 2 harakat). Mad Thabi'i / Mad Asli: Pada lafaz ِفَﻼِﺘْاﺧَو ,ِﺎرَاﻟﻨﱠﮭَو ِﻞْاﻟﱠﯿ. Qalqalah Sughra: Pada lafaz ِﻖْﻠَﺧ( huruf qaf kasrah berada di tengah bacaan; jika diwakafkan menjadi Qalqalah Kubra) dan َﻚَﻨٰﺤْﺒُﺳ( huruf ba sukun di tengah kata). Q.S. ar-Rahman/55: 33 & Hadis tentang Iptek (Soal 2, 4–6, 8, 10): Q.S. ar-Rahman/55: 33 menyeru golongan jin dan manusia (ِﺲْﻧِْ اﻻَو ﻦﱢِﺠْاﻟ َﺮَﺸْﻌَﻤٰﯾ )bahwa apabila mereka sanggup menembus penjuru langit dan bumi, silakan menembusnya, namun mereka tidak akan mampu menembusnya kecuali dengan kekuatan/kekuasaan ( ٍﻦٰﻄْﻠُﺴِﺑ ﻻﱠِا ,)yang ditafsirkan para ulama sebagai kekuatan ilmu pengetahuan dan teknologi yang diridai Allah. Hadis Nabi saw. juga menegaskan kewajiban menuntut ilmu: \"Thalabul 'ilmi faridhatun 'ala kulli muslim\" (Menuntut ilmu itu wajib atas setiap muslim) serta hadis riwayat Muslim bahwa barang siapa menempuh jalan untuk mencari ilmu, Allah akan memudahkan baginya jalan menuju surga. Etika & Dampak Negatif Berpikir Kritis yang Keliru (Soal 7, 9, 13): Berpikir kritis dalam Islam harus dibingkai iman dan adab. Apabila berpikir kritis tidak dilandasi akhlak dan petunjuk wahyu, dampak negatifnya antara lain munculnya sikap sombong merasa paling pintar, mudah meremehkan pendapat orang lain, perdebatan tanpa solusi, hingga keraguan terhadap kebenaran agama."
      },
      {
        "judul": "Cabang-Cabang Iman / Syu'abul Iman",
        "isi": "B. Cabang-Cabang Iman / Syu'abul Iman (Soal No. 14 – 27) Hakikat Islam & Syu'abul Iman (Soal 23, 27): Hakikat agama Islam adalah ketundukan dan kepatuhan total kepada Allah Swt. yang mendatangkan keselamatan dan kedamaian bagi seluruh alam (rahmatan lil 'alamin). Iman memiliki lebih dari 70 cabang (Syu'abul Iman) yang meliputi keyakinan hati, ucapan lisan, dan perbuatan anggota badan. Mensyukuri Nikmat Allah (Soal 14, 19): Syukur diwujudkan melalui hati (mengakui nikmat berasal dari Allah), lisan (mengucap alhamdulillah), dan perbuatan (menggunakan nikmat untuk ketaatan). Manfaat bersyukur adalah ketenangan batin dan ditambahnya nikmat oleh Allah (Q.S. Ibrahim/14: 7), sedangkan akibat kufur nikmat adalah kegelisahan hati dan azab Allah yang pedih. Memenuhi Janji (Soal 15, 25): Menepati janji merupakan ciri orang beriman dan tanda kejujuran. Manfaatnya antara lain menumbuhkan kepercayaan orang lain, mempererat ukhuwah, dan menghindarkan diri dari sifat munafik. Memelihara Lisan & Bijak Bermedia Sosial (Soal 16, 18, 20, 22, 24, 26): Menjaga lisan berarti bertutur kata yang baik atau diam (falyaqul khairan au liyasmut). Di era digital, lisan diwakili oleh jari di media sosial; umat Islam wajib melakukan tabayyun (klarifikasi/cek kebenaran berita) sebelum membagikan informasi agar terhindar dari penyebaran berita bohong (hoaks), fitnah, dan ujaran kebencian. Menutup Aib Orang Lain (Soal 17, 21): Menutup aib sesama muslim mendatangkan balasan berupa ditutupnya aib pelakunya oleh Allah di dunia dan akhirat. Namun, para ulama membolehkan membuka keburukan/aib seseorang dalam kondisi darurat tertentu demi kemaslahatan, seperti: (1) mengadukan kezaliman kepada hakim/pihak berwenang untuk mencari keadilan; (2) meminta fatwa atau nasihat penyelesaian masalah kepada ulama/konselor; (3) memperingatkan masyarakat agar terhindar dari bahaya penipuan atau kejahatan; dan (4) menjadi saksi di pengadilan."
      },
      {
        "judul": "Menghindari Perkelahian Pelajar, Perjudian, Khamr, & Narkoba",
        "isi": "C. Menghindari Perkelahian Pelajar, Perjudian, Khamr, & Narkoba (Soal No. 28 – 40) Perkelahian Pelajar & Perundungan / Bullying (Soal 28, 30, 31, 35–38): Menurut psikolog Sarlito Wirawan Sarwono, kenakalan remaja (pelajar) adalah semua perilaku yang menyimpang dari norma-norma hukum pidana yang dilakukan oleh remaja dan merugikan dirinya sendiri maupun orang lain. Faktor penyebabnya meliputi krisis identitas, kontrol diri yang lemah, pengaruh lingkungan/teman sebaya, dan kurangnya perhatian keluarga. Dampaknya merusak masa depan, menimbulkan trauma fisik/psikis, dan melanggar tujuan syariat Islam (Maqashid Syariah, khususnya menjaga jiwa/hifzhun nafs dan kehormatan). Langkah preventif efektif memutus perundungan meliputi penguatan pendidikan karakter, budaya lapor yang aman, keteladanan guru/orang tua, dan pendampingan konseling bagi pelaku maupun korban. Larangan Khamr, Narkoba, & Perjudian / Maysir (Soal 29, 32–34, 39, 40): Tahapan Pengharaman Khamr & Ayat Terakhir: Larangan khamr diturunkan secara bertahap dan ditutup secara tegas oleh Q.S. al-Ma'idah/5: 90–91 yang mengharamkan secara mutlak khamr (minuman memabukkan), maysir (perjudian), berkorban untuk berhala, dan mengundi nasib sebagai perbuatan keji termasuk perbuatan setan. Pengertian & Bahan Dasar Khamr: Setiap zat yang memabukkan dan menutup akal sehat hukumnya haram, baik sedikit maupun banyak. Secara historis dan fikih, khamr dibuat dari perasan buah-buahan yang difermentasi hingga memabukkan, seperti anggur, kurma, kismis, gandum, maupun buah-buahan manis lainnya. Akibat Buruk & Cara Menghindari: Minum khamr dan menyalahgunakan narkoba merusak akal (hifzhul 'aql), menghancurkan kesehatan saraf/organ tubuh, memicu tindak kriminalitas, dan menghalangi zikir serta salat. Cara menghindarinya adalah memperkuat iman, memilih lingkungan pergaulan yang saleh, mengisi waktu dengan kegiatan positif, serta berani menolak ajakan teman. Perjudian (Maysir): Setiap aktivitas permainan atau taruhan yang mengandung unsur untung- untungan (spekulasi) di mana satu pihak diuntungkan dan pihak lain dirugikan secara batil, termasuk judi daring (slot/taruhan online) maupun taruhan pertandingan."
      }
    ],
