    "materiRingkas": [
      {
        "judul": "Sikap dan Perilaku Wirausaha",
        "isi": "Bab 1: Sikap dan Perilaku Wirausaha Pengertian Wirausaha: Secara etimologis berasal dari kata wira (pejuang, pahlawan, manusia unggul, teladan) dan usaha (perbuatan untuk mencapai tujuan). Istilah entrepreneur pertama kali dikenalkan oleh ekonom Prancis Richard Cantillon pada awal abad ke-18. Menurut Joseph Schumpeter, wirausaha adalah inovator yang melakukan perubahan di pasar melalui pengenalan produk baru, metode produksi baru, pembukaan pasar baru, sumber pasokan baru, atau organisasi baru. Karakter Wirausaha & 10 D Bygrave: Karakter dasar wirausaha mencakup kreatif, inovatif, berani mengambil risiko terukur, kepemimpinan, mampu berkomunikasi, kerja sama, mandiri, percaya diri, jujur, dan pantang menyerah. Menurut Bygrave, terdapat 10 karakter wirausaha (10 D): Dream (impian), Decisiveness (keputusan cepat dan tepat), Doers (tindak lanjut nyata), Determination (tekad dan tanggung jawab), Dedication (dedikasi tinggi), Devotion (fokus dan tak kenal lelah), Details (analisis rinci), Destiny (merumuskan tujuan), Dollars (uang bukan semata tujuan utama), dan Distribute (membagi tugas/wewenang). Cara Mengembangkan Kreativitas: Dilakukan melalui mindset continuous improvement (perbaikan berkelanjutan), diskusi dan interaksi, sesi brainstorming (adu ide bersama tim), traveling dan bertemu orang baru, membuat Idea Bank (wadah pencatatan ide), serta pantang menyerah. Manfaat & Peran Wirausaha dalam Perekonomian: Manfaat pribadi meliputi menciptakan lapangan kerja, kebebasan mencapai tujuan, tidak terikat jam kerja kaku, menunjukkan potensi diri, dan meraih laba optimal. Dalam perekonomian nasional, wirausaha berperan membuka lapangan kerja, meningkatkan pendapatan nasional, mengurangi kesenjangan ekonomi, mendorong masyarakat adil makmur, menghasilkan devisa ekspor, meningkatkan investasi dalam negeri, serta menyumbang penerimaan pajak negara. Perilaku & Aspek Kerja Prestatif: Kerja prestatif adalah perilaku selalu ingin maju, antusias, tidak mudah mengeluh, dan tidak cepat puas (menurut Stephen Covey ditopang 4 sisi potensial: , , , dan ). Lima aspek kerja prestatif meliputi: (1) (bekerja tulus penuh pengabdian); (2) (tidak tergesa-gesa dan tidak mencampuradukkan masalah pribadi dengan pekerjaan); (3) (menggunakan pikiran tajam, kalkulasi, komunikasi, dan negosiasi); (4) (mengerahkan sumber daya secara optimal); dan (5) (mengorganisasikan pekerjaan secara terpadu hingga selesai sempurna).self awarenessconscienceindependent willcreative imaginationKerja ikhlasKerja mawas diriKerja cerdasKerja kerasKerja tuntas"
      },
      {
        "judul": "Peluang Usaha",
        "isi": "Bab 2: Peluang Usaha Pengertian & Ciri Peluang Usaha: Peluang usaha adalah kesempatan yang dimiliki seseorang untuk mencapai tujuan usaha (laba, kepuasan, kemandirian) dengan memanfaatkan sumber daya yang ada (modal, pengetahuan, keterampilan, relasi). Peluang usaha yang baik bersifat orisinal, mengantisipasi perubahan pasar, sesuai minat, teruji kelayakannya, kreatif, dan diyakini dapat diwujudkan. Peluang usaha yang potensial memiliki nilai jual, bukan ambisi pribadi semata, mampu bertahan lama di pasar, tidak menghabiskan modal berlebihan, serta dapat ditingkatkan skalanya menjadi industri. Faktor Keberhasilan & Kegagalan Usaha: Keberhasilan dipengaruhi oleh faktor manusia (kepribadian, ilmu pengetahuan, pengalaman), keuangan (modal), perencanaan matang, pemasaran, serta falsafah DORAEMON menurut Adyaksa Dault (Dream, Opportunity, Reform, Action, Energy, Mapping, Organizing, Network). Sebaliknya, menurut Zimmerer, kegagalan usaha disebabkan oleh ketidakmampuan manajerial, kurang pengalaman, gagal mengelola keuangan, lokasi kurang strategis, gagal perencanaan, sikap kurang sungguh-sungguh, ketidakmampuan melakukan transisi kewirausahaan, dan kurang pengawasan peralatan. Kreativitas & Jenis Inovasi (Kuratko): Pemanfaatan peluang secara kreatif dilakukan melalui to create (menciptakan hal baru dari yang belum ada), to modify (memodifikasi fungsi/bentuk yang sudah ada), dan to combine (mengombinasikan dua hal atau lebih). Menurut Kuratko, terdapat empat jenis inovasi: (1) Invensi (penemuan baru); (2) Ekstensi (pengembangan dari yang sudah ada); (3) Duplikasi (penggandaan produk yang sudah ada dan terkenal); dan (4) Sintesis (penggabungan beberapa konsep/formula menjadi formula baru). Sumber Peluang & Pendekatan Analisis Peluang Usaha: Sumber peluang berasal dari faktor internal (pengetahuan, pengalaman pribadi, pengalaman orang lain, intuisi) dan faktor eksternal (masalah yang belum terpecahkan, kesulitan sehari-hari, kebutuhan yang belum terpenuhi, pemikiran menciptakan hal baru). Pendekatan analisisnya meliputi: (1) Analisis SWOT (faktor internal: Strength/kekuatan dan Weakness/kelemahan; faktor eksternal: Opportunity/peluang dan Threat/ancaman); (2) Analisis 5W + 1H (What, Where, When, Why, Who, How); dan (3) Studi Kelayakan Usaha (penemuan ide, penelitian usaha, evaluasi, pengurutan usulan layak, perencanaan pelaksanaan, dan pelaksanaan) untuk menghindari keterlanjuran investasi besar pada bisnis yang tidak menguntungkan."
      },
      {
        "judul": "Hak Atas Kekayaan Intelektual (HAKI)",
        "isi": "Bab 3: Hak Atas Kekayaan Intelektual (HAKI) Pengertian, Tujuan, Sifat, & Prinsip HAKI: HAKI adalah hak atas kekayaan yang lahir dari kemampuan intelektual manusia di bidang ilmu pengetahuan, seni, sastra, maupun teknologi yang dilindungi hukum. Tujuannya mencegah pelanggaran hak milik orang lain, meningkatkan daya saing dan pangsa pasar, serta menjadi acuan strategi riset bisnis. HAKI memiliki dua sifat: (1) memiliki jangka waktu terbatas (setelah habis menjadi milik umum/public domain, kecuali merek yang dapat diperpanjang); dan (2) bersifat eksklusif dan mutlak (memberi hak monopoli kepada pemilik untuk melarang pihak lain meniru tanpa izin). Empat prinsip HAKI adalah prinsip ekonomi, prinsip keadilan, prinsip kebudayaan, dan prinsip sosial. Klasifikasi HAKI & Dasar Hukum di Indonesia: Berdasarkan WIPO, HAKI terbagi menjadi dua kelompok besar: 1. Hak Cipta (Copyright — UU No. 19 Tahun 2002): Hak eksklusif bagi pencipta di bidang ilmu pengetahuan, seni, dan sastra (buku, program komputer, ceramah, alat peraga, lagu/musik, drama/tari, seni rupa, arsitektur, peta, batik, fotografi, sinematografi). Mencakup hak ekonomi (manfaat finansial) dan hak moral (hak yang melekat abadi pada pencipta dan tidak dapat dihilangkan meski hak ciptanya dialihkan). 2. Hak Kekayaan Industri (Industrial Property Right): Meliputi Hak Paten (UU No. 14 Tahun 2001 — perlindungan invensi teknologi), Hak Merek (UU No. 15 Tahun 2001 — tanda pembeda berupa gambar, nama, kata, huruf, angka, susunan warna), Perlindungan Varietas Tanaman / PVT (UU No. 29 Tahun 2000), Rahasia Dagang (UU No. 30 Tahun 2000 — informasi bisnis/teknologi bernilai ekonomi yang dijaga kerahasiaannya), Desain Industri (UU No. 31 Tahun 2000 — kreasi bentuk, konfigurasi, atau komposisi garis/warna 2D atau 3D yang estetis), Desain Tata Letak Sirkuit Terpadu / DTLST (UU No. 32 Tahun 2000 — peletakan 3D elemen aktif pada bahan semikonduktor), dan Indikasi Geografis (tanda asal muasal barang karena faktor geografis alam/manusia). Syarat Paten, Invensi yang Dikecualikan, & Pemeliharaan Paten: Karya intelektual dapat dipatenkan apabila memenuhi tiga syarat substantif: (1) Bersifat baru (kebaruan) (belum pernah dipublikasikan sebelum tanggal penerimaan permohonan); (2) Bersifat inventif (mengandung langkah inventif yang tidak terduga bagi ahli di bidangnya); dan (3) Bersifat aplikatif (dapat diterapkan berulang kali dalam industri). Invensi yang tidak dapat dipatenkan meliputi: invensi yang bertentangan dengan hukum, moralitas agama, ketertiban umum/kesusilaan; metode pemeriksaan, perawatan, pengobatan, dan pembedahan pada manusia/hewan; teori dan metode ilmu pengetahuan serta rumus matematika; serta semua makhluk hidup (kecuali jasad renik) dan proses biologis esensial. Pemegang paten wajib membayar biaya pemeliharaan tahunan sesuai tanggal pemberian paten; jika tidak dibayar selama 3 tahun berturut-turut, paten dinyatakan batal demi hukum."
      }
    ],
