        "C": "Higher-paying positions in multinational companies depend solely on physical strength.",
        "D": "English skills are only useful for administrative secretaries, not technical engineers.",
        "E": "Graduates with strong technical skills will be rejected if they speak English.Text 4 (For Questions 37–40): Artificial Intelligence and Automation in Modern ManufacturingThe rapid adoption of Artificial Intelligence (AI) and smart automation is reshaping modern manufacturing industries. Rather than eliminating human relevance, these technologies significantly elevate production precision and workplace efficiency. AI-powered predictive maintenance systems can analyze sensor data in real time to detect abnormal machine vibrations before a major breakdown occurs. As a result, factories experience less unplanned downtime and lower repair costs. Additionally, automated quality control cameras inspect thousands of products per minute with higher accuracy than the human eye, ensuring consistent product standards. Therefore, embracing AI-driven automation is a strategic necessity for industries aiming to remain competitive, while workers must continuously upgrade their digital skills to operate alongside intelligent machines."
